        m.Term.Select(qual, m.Term.Name("filter")), args
    ) if args.values.size == 1 &&
        (isStringExpr(qual) || (qual match {
          case m.Term.Name(n) => ctx.localStrings.contains(n) || ctx.paramTypes.get(n).contains("String")
          case _ => false
