        q <- renderTerm(qual, ctx)
        f <- args.values.head match
          // `{ index => … }` (brace-block syntax) — see the range `.foreach` case's own comment,
          // same unwrap, same reason.
          case m.Term.Block(List(fn2: m.Term.Function)) =>
