    case m.Term.Apply.After_4_6_0(m.Term.Select(qual, m.Term.Name("startsWith")), args)
        if args.values.size == 2 =>
      for
        q      <- renderTerm(qual, ctx)
        prefix <- renderTerm(args.values.head, ctx)
        at     <- renderTerm(args.values(1), ctx)
