      renderTerm(qual, ctx).map(q => s"$q.collect::<Vec<_>>()")

    // `Stream.emit(x)` → `_eff.stream_emit(x)` (inside a runStream block).
    case m.Term.Apply.After_4_6_0(
        m.Term.Select(m.Term.Name("Stream"), m.Term.Name("emit")),
        args
